import React from 'react'
import Typography from '@mui/material/Typography'

export const PromptPage = ({user}) => {
  return (
    <>
      <Typography variant="h1" align="center" gutterBottom>
        Prompt Page
      </Typography>

      <Typography variant="body1">
        Welcome, {user.name}
      </Typography>
    </>
  )
}

export default PromptPage
